args.CommandLine:
Get-ChildItem -Path "C:\Users\ivan_\.gemini\antigravity\brain" -Directory | ForEach-Object { 
    $id = $_.Name
    $log = Join-Path $_.FullName ".system_generated\logs\transcript.jsonl"
    if (Test-Path $log) {
        $size = (Get-Item $log).Length
        $mtime = (Get-Item $log).LastWriteTime
        $firstLine = (Get-Content $log -Head 1)
        [PSCustomObject]@{
            Id = $id
            Size = $size
            LastWriteTime = $mtime
            Sample = ($firstLine | Select-String -Pattern "carrinho|renner|rfid" -Quiet)
        }
    }
} | Format-Table -AutoSize
